package com.bank.fair.repo;

import java.math.BigDecimal;

// Shared dependency with a FIXED delay so neither stack can saturate it.
// This isolates the concurrency MODEL instead of benchmarking PostgreSQL.
public class FixedDelayAccountRepository {
    private static final long FIXED_DELAY_MS = 5;  // identical for both stacks

    public BigDecimal findBalance(String accountId) {
        try { Thread.sleep(FIXED_DELAY_MS); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return accountId.equals("SAV2001") ? new BigDecimal("1000000") : new BigDecimal("250000");
    }
}
