package com.bank.fair.service;

import com.bank.fair.repo.FixedDelayAccountRepository;
import java.math.BigDecimal;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

// Thread-per-request blocking model with a CORRECTLY SIZED pool.
public class BlockingLookupService implements AutoCloseable {
    private final FixedDelayAccountRepository repo;
    private final ExecutorService pool;

    public BlockingLookupService(FixedDelayAccountRepository repo, int poolSize) {
        this.repo = repo;
        // Match the model: cores*2 is a sane blocking pool; NOT 2, NOT 1000.
        this.pool = Executors.newFixedThreadPool(poolSize);
    }

    public Future<BigDecimal> lookup(String accountId) {
        return pool.submit(() -> repo.findBalance(accountId));  // blocks a thread for 5ms
    }

    @Override public void close() { pool.shutdown(); }
}
