package com.bank.fair.service;

import com.bank.fair.repo.FixedDelayAccountRepository;
import java.math.BigDecimal;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;

// Simulates a reactive stack: few threads, but MANY tiny short-lived objects
// per request (operator wrappers, signals) — the thing that stresses young-gen.
public class ReactiveLookupService {
    private final FixedDelayAccountRepository repo;
    private final ExecutorService eventLoop;

    public ReactiveLookupService(FixedDelayAccountRepository repo, ExecutorService eventLoop) {
        this.repo = repo;
        this.eventLoop = eventLoop;  // small, non-blocking-style pool
    }

    public CompletableFuture<BigDecimal> lookup(String accountId) {
        return CompletableFuture.supplyAsync(() -> {
            // Allocate many tiny short-lived objects, like R2DBC's pipeline does.
            Object[] churn = new Object[32];
            for (int i = 0; i < churn.length; i++) churn[i] = new Signal(accountId, i);
            BigDecimal balance = repo.findBalance(accountId);
            return balance.add(BigDecimal.ZERO);  // another short-lived object
        }, eventLoop);
    }

    // Tiny per-request object representing a reactive signal/wrapper.
    private record Signal(String accountId, int seq) { }
}
