package com.bank.fair.bench;

import java.util.function.Supplier;
import java.util.concurrent.Future;
import org.HdrHistogram.Histogram;

// Open-model driver: fixed arrival schedule + expected-interval correction,
// applied IDENTICALLY to both stacks so the comparison is fair.
public class FairBenchmark {
    private final long scheduleNs;  // one request every scheduleNs

    public FairBenchmark(long scheduleNs) { this.scheduleNs = scheduleNs; }

    // task returns a Future we await; we measure from the SCHEDULED send time.
    public Histogram run(int requests, Supplier<Future<?>> task) throws Exception {
        Histogram h = new Histogram(60_000_000_000L, 3);
        long startRun = System.nanoTime();
        for (int i = 0; i < requests; i++) {
            long scheduledAt = startRun + (long) i * scheduleNs;  // fixed schedule
            // Open model: do NOT wait to dispatch; measure from scheduledAt.
            Future<?> f = task.get();
            f.get();                                  // await this request's response
            long latencyNs = System.nanoTime() - scheduledAt;
            h.recordValueWithExpectedInterval(latencyNs, scheduleNs);  // defeat omission
        }
        return h;
    }
}
