package com.bank.fair;

import com.bank.fair.bench.FairBenchmark;
import com.bank.fair.repo.FixedDelayAccountRepository;
import com.bank.fair.service.BlockingLookupService;
import com.bank.fair.service.ReactiveLookupService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;
import org.HdrHistogram.Histogram;

public class FairBenchmarkDemo {
    private static final Logger log = Logger.getLogger(FairBenchmarkDemo.class.getName());

    public static void main(String[] args) throws Exception {
        FixedDelayAccountRepository repo = new FixedDelayAccountRepository(); // shared, unsaturated
        int requests = 20_000;
        long scheduleNs = 100_000; // 10k req/s open-model schedule

        int cores = Runtime.getRuntime().availableProcessors();
        FairBenchmark bench = new FairBenchmark(scheduleNs);

        log.info("Blocking stack with CORRECTLY SIZED pool (cores*2)...");
        try (BlockingLookupService blocking = new BlockingLookupService(repo, cores * 2)) {
            Histogram hb = bench.run(requests, () -> blocking.lookup("SAV2001"));
            logResult("BLOCKING", hb);
        }

        log.info("Reactive stack (few threads, many tiny objects per request)...");
        var eventLoop = Executors.newFixedThreadPool(cores);
        ReactiveLookupService reactive = new ReactiveLookupService(repo, eventLoop);
        Histogram hr = bench.run(requests, () -> reactive.lookup("SAV2001"));
        logResult("REACTIVE", hr);
        eventLoop.shutdown();

        log.warning("Fair rules: open model, shared unsaturated repo, matched pools, "
                + "ample young-gen (-Xmn) so R2DBC tiny objects don't skew GC.");
    }

    private static void logResult(String name, Histogram h) {
        log.info(() -> String.format("%s median=%.2fms p99=%.2fms p99.9=%.2fms",
            name,
            h.getValueAtPercentile(50) / 1_000_000.0,
            h.getValueAtPercentile(99) / 1_000_000.0,
            h.getValueAtPercentile(99.9) / 1_000_000.0));
    }
}
