package com.bank.fair;

import com.bank.fair.bench.FairBenchmark;
import com.bank.fair.repo.FixedDelayAccountRepository;
import com.bank.fair.service.BlockingLookupService;
import org.HdrHistogram.Histogram;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FairBenchmarkTest {

    @Test
    void sharedRepoKeepsDependencyIdenticalForBothStacks() throws Exception {
        FixedDelayAccountRepository repo = new FixedDelayAccountRepository();
        FairBenchmark bench = new FairBenchmark(100_000);
        try (BlockingLookupService blocking = new BlockingLookupService(repo, 8)) {
            Histogram h = bench.run(2_000, () -> blocking.lookup("SAV2001"));
            assertEquals(2_000, h.getTotalCount());
            // 5ms fixed dependency delay must dominate the median.
            assertTrue(h.getValueAtPercentile(50) >= 4_000_000L,
                "median should reflect the 5ms shared repo delay");
        }
    }
}
